// Dashboard-scoped virtual course catalog.
// Each entry maps to a persistent `courses` row via `slug` (created on demand
// by ensureCatalogCourse). Content (chapters/lessons) is generated by AI when
// the learner opens the course.

export type BoardEnum = "cbse" | "state_board" | "icse" | "cambridge" | "ib" | "nios" | "other";
export type DifficultyEnum = "beginner" | "intermediate" | "advanced";

export type CatalogCourse = {
  slug: string;
  title: string;
  subject: string;
  description: string;
  board: BoardEnum;
  class_min: number;
  class_max: number;
  difficulty: DifficultyEnum;
  estimated_hours: number;
  learning_objectives: string[];
};

export type CatalogCategory = {
  key: string;
  label: string;
  emoji: string;
  description: string;
  courses: CatalogCourse[];
};

export type CatalogScope = {
  role: "school" | "college" | "professional";
  title: string;
  description: string;
  categories: CatalogCategory[];
};

/* -------------------------------------------------------------------------- */
/* School (Classes 1–12)                                                       */
/* -------------------------------------------------------------------------- */

const SCHOOL_SUBJECTS_1_5 = [
  "English",
  "Mathematics",
  "Environmental Science (EVS)",
  "General Science",
  "Social Studies",
  "Computer Science",
  "General Knowledge",
];

const SCHOOL_SUBJECTS_6_10 = [
  "English",
  "Mathematics",
  "Physics",
  "Chemistry",
  "Biology",
  "General Science",
  "Social Science",
  "History",
  "Geography",
  "Civics",
  "Economics",
  "Computer Science",
];

const SCHOOL_11_12: Record<string, string[]> = {
  Science: ["Physics", "Chemistry", "Mathematics", "Biology", "Computer Science", "English"],
  Commerce: [
    "Accountancy",
    "Business Studies",
    "Economics",
    "Commerce",
    "Mathematics",
    "Computer Applications",
    "English",
  ],
  Humanities: [
    "History",
    "Geography",
    "Political Science",
    "Economics",
    "Psychology",
    "Sociology",
    "English",
  ],
};

function slugify(s: string): string {
  return s
    .toLowerCase()
    .replace(/\([^)]*\)/g, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");
}

function schoolCourse(classNum: number, subject: string, stream?: string): CatalogCourse {
  const cls = `Class ${classNum}`;
  const label = stream ? `${cls} · ${stream}` : cls;
  return {
    slug: `nova-school-c${classNum}${stream ? "-" + slugify(stream) : ""}-${slugify(subject)}`,
    title: `${subject} — ${label}`,
    subject,
    description: `AI-personalized ${subject} for ${label}. Chapters, lessons, notes, MCQs, assignments, quizzes, mock tests, and revision — generated on demand.`,
    board: "cbse",
    class_min: classNum,
    class_max: classNum,
    difficulty: classNum <= 5 ? "beginner" : classNum <= 8 ? "beginner" : classNum <= 10 ? "intermediate" : "advanced",
    estimated_hours: classNum <= 5 ? 20 : classNum <= 10 ? 40 : 60,
    learning_objectives: [
      `Master the ${label} ${subject} syllabus`,
      "Practice with adaptive AI questions",
      "Track progress week by week",
    ],
  };
}

function buildSchoolCategories(): CatalogCategory[] {
  const cats: CatalogCategory[] = [];
  for (let c = 1; c <= 5; c++) {
    cats.push({
      key: `class-${c}`,
      label: `Class ${c}`,
      emoji: "🌱",
      description: `Foundation subjects for Class ${c}`,
      courses: SCHOOL_SUBJECTS_1_5.map((s) => schoolCourse(c, s)),
    });
  }
  for (let c = 6; c <= 10; c++) {
    cats.push({
      key: `class-${c}`,
      label: `Class ${c}`,
      emoji: c <= 8 ? "📗" : "📘",
      description: `Core subjects for Class ${c}`,
      courses: SCHOOL_SUBJECTS_6_10.map((s) => schoolCourse(c, s)),
    });
  }
  for (const c of [11, 12]) {
    for (const stream of Object.keys(SCHOOL_11_12)) {
      cats.push({
        key: `class-${c}-${slugify(stream)}`,
        label: `Class ${c} · ${stream}`,
        emoji: stream === "Science" ? "🔬" : stream === "Commerce" ? "📊" : "🏛️",
        description: `${stream} stream for Class ${c}`,
        courses: SCHOOL_11_12[stream].map((s) => schoolCourse(c, s, stream)),
      });
    }
  }
  return cats;
}

