/* -------------------------------------------------------------------------- */
/* Public API                                                                  */
/* -------------------------------------------------------------------------- */

export const SCHOOL_CATALOG: CatalogScope = {
  role: "school",
  title: "School Learning",
  description: "Class-wise subjects for Classes 1–12",
  categories: buildSchoolCategories(),
};

export const COLLEGE_CATALOG: CatalogScope = {
  role: "college",
  title: "College Learning",
  description: "Tracks aligned to Indian & global undergraduate programs",
  categories: buildCollegeCategories(),
};

export const PRO_CATALOG: CatalogScope = {
  role: "professional",
  title: "Professional Upskilling",
  description: "In-demand tracks curated for working professionals",
  categories: buildProCategories(),
};

export const CATALOG_BY_ROLE = {
  student: SCHOOL_CATALOG,
  college_student: COLLEGE_CATALOG,
  professional: PRO_CATALOG,
} as const;

export function findCatalogCourse(slug: string): CatalogCourse | null {
  for (const scope of [SCHOOL_CATALOG, COLLEGE_CATALOG, PRO_CATALOG]) {
    for (const cat of scope.categories) {
      const hit = cat.courses.find((c) => c.slug === slug);
      if (hit) return hit;
    }
  }
  return null;
}
